from pathlib import Path
from html import escape
import re

root = Path(__file__).resolve().parent.parent
root.mkdir(exist_ok=True)
css = '''*{box-sizing:border-box}body{margin:0;background:#111a19;color:#e8eeeb;font:17px/1.8 system-ui,sans-serif}a{color:#92dec7;text-underline-offset:5px}a:hover{color:#fff}header,main,footer{max-width:1040px;margin:auto;padding:24px}header{display:flex;gap:24px;align-items:center;border-bottom:1px solid #30423d}header a:first-child{font-weight:750;margin-right:auto;text-decoration:none}nav{display:flex;flex-wrap:wrap;gap:20px}h1{font-size:clamp(38px,7vw,68px);line-height:1.2;letter-spacing:-.03em;margin:20px 0}h2{margin-top:48px;font-size:27px}h3{font-size:20px}p{max-width:760px}.eyebrow{color:#92dec7;letter-spacing:.12em;font-size:13px}section{padding:20px 0}.lead{font-size:21px;color:#bbcfc7}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.card{background:#1a2925;padding:26px;border:1px solid #355247;border-radius:16px}.button{display:inline-block;padding:10px 20px;background:#a2e5cf;color:#13271f;border-radius:9px;text-decoration:none;font-weight:700}.button:hover{background:#cdf5e6;color:#13271f}.notice{border-left:3px solid #d5b97b;padding:10px 18px;background:#27271e;color:#e8d9b8;font-size:14px}footer{margin-top:50px;border-top:1px solid #30423d;color:#afc0b9;font-size:14px}li{margin:8px 0}code{overflow-wrap:anywhere}a:focus-visible{outline:3px solid #f7d983;outline-offset:5px}@media(max-width:600px){header{align-items:flex-start;flex-direction:column;gap:10px}main{padding:20px}h2{margin-top:32px}}'''
(root/'style.css').write_text(css,encoding='utf-8')
(root/'.nojekyll').touch()
pages = {}

def page(path,title,body,en=False):
    if path in ('index.html', 'memogyt/index.html'):
        body = re.sub(r'<h1>.*?</h1>', '<h1>思いつきを、AIと育てる。</h1>', body, count=1)
        body = re.sub(r'<p class="lead">.*?</p>', '<p class="lead">Memogytは、AI時代のクラウド（GitHub）同期型メモ帳です。<br>オフラインでアイデアを書き留め、好きなAIへつないで、壁打ちから次の一歩へ。</p>', body, count=1)
    pages[path] = body
page('index.html','アプリ一覧','''<section><p class="eyebrow">SMALL TOOLS, EVERYDAY IDEAS</p><h1>思いつきから、<br>次の一歩へ。</h1><p class="lead">tripleskyのアプリ紹介と、使い方・プライバシー情報。</p></section><div class="cards"><article class="card"><h2>Memogyt</h2><p>オフラインで書き留め、必要なときに共有するメモ帳。テキストとMarkdownに対応しています。</p><a class="button" href="memogyt/index.html">Memogytについて</a></article></div>''')
page('memogyt/index.html','Memogyt','''<section><p class="eyebrow">LOCAL NOTES · MARKDOWN · SHARE</p><h1>アイデアを、<br>思いついたその場で。</h1><p class="lead">Memogytは、この端末に自動保存するメモ帳です。通信できない場所でも書き留めて、あとからAIとの壁打ちやGitHubでの管理に使えます。</p></section><div class="cards"><article class="card"><h3>まずは、書くだけ</h3><p>オフラインで作成・編集。ファイル名や本文で検索でき、フォルダで整理できます。</p></article><article class="card"><h3>Markdownで整理</h3><p>見出し・箇条書き・表をプレビュー。日本語／英語と複数のテーマを切り替えられます。</p></article><article class="card"><h3>必要なときに共有</h3><p>本文を確認・編集してChatGPT、Claude、Codexへ。対応状況に応じて、コピーして開いた先へ貼り付けます。投稿は利用者が行います。</p></article></div><h2>GitHub連携は任意です</h2><p>入力のたびには送信しません。同期ボタンから変更を確認して反映し、1回の同期は最大100件。競合したメモは確認を後回しにできます。</p><p>GitHub連携にはGitHubアカウント、初期化済みリポジトリ、必要な権限のPersonal Access Tokenが必要です。通常のメモ利用には不要です。</p><h2>配布について</h2><p>Windows版のStore認定は完了しています。Mac・iPhone版とAI共有機能の正式配布は準備中です。公開済みの配布先と提供機能を確認してから、このページへ掲載します。</p><p><a href="privacy.html">プライバシーポリシー</a> · <a href="support.html">使い方・サポート</a> · <a href="en.html" lang="en">English</a></p>''')
page('memogyt/en.html','Memogyt','''<p class="eyebrow">LOCAL NOTES · MARKDOWN · SHARE</p><h1>Capture ideas.<br>Keep them moving.</h1><p class="lead">Memogyt saves notes on your device. Write offline, organize text and Markdown, and share an idea when you are ready.</p><h2>Your everyday notebook</h2><ul><li>Automatic local saving and offline editing.</li><li>Folders, filename and full-text search.</li><li>Markdown preview with headings, lists and tables.</li><li>Japanese and English interfaces with multiple themes.</li></ul><h2>Optional connections</h2><p>Preview and edit text before opening ChatGPT, Claude or Codex. Copy and paste where direct text handoff is unavailable. You submit the message in the destination app.</p><p>GitHub sync runs when requested, with up to 100 changes per operation. It requires a GitHub account, an initialized repository and a Personal Access Token with suitable permissions. Local notes require none of these.</p><h2>Availability</h2><p>Windows Store certification is complete. Mac, iPhone and AI-sharing release preparation is ongoing. Verified public download links will be added when available.</p><p><a href="privacy-en.html">Privacy policy</a> · <a href="support-en.html">Support</a> · <a href="index.html" lang="ja">日本語</a></p>''',True)
ja='''<h1>プライバシーポリシー</h1><p>対象：Memogytの公開準備中のMac／iPhone版およびAI共有機能。施行日と連絡先は未確定です。</p><h2>端末内のデータ</h2><p>通常のメモ作成・編集にアカウントは不要です。メモ、設定、バックアップ、診断ログを端末内に保存します。メモファイルを暗号化保管する機能はありません。独自の広告・アクセス解析・自動診断ログ送信は行いません。</p><h2>任意のGitHub連携</h2><p>接続確認、取得、利用者が指示した同期などではGitHubと通信します。入力のたびに送信しません。同期すると、対象のメモ本文・ファイル名・変更情報が指定リポジトリに保存されます。公開リポジトリでは第三者も閲覧できます。</p><p>PATはMac／iPhoneのKeychainに保存し、GitHub認証に使います。開発者の独自サーバーへメモや認証情報を送信する機能はありません。<a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHubのプライバシー方針</a>も確認してください。</p><h2>任意のAI共有とクリップボード</h2><p>利用者がプレビューした文章を、コピーまたは「送信／開く」の操作で渡します。コピーした文章はOSのクリップボードに入り、OS設定によって履歴や他端末との共有の対象となることがあります。</p><p>ChatGPT・Claudeは本文をURLに含めずに開き、利用者が貼り付けます。デスクトップの対応するCodex起動方法では本文を起動URLに含めることがあります。URLや起動情報がOS・アプリ等に残る可能性があります。iPhoneでは本文を含めずにCodexを開きます。外部アプリへの投稿や回答の自動取得は行いません。</p><p>共有した内容は送信先サービスの規約・プライバシー方針およびアカウント設定に従って扱われます。Memogytから相手側の保存・学習利用・削除を制御することはできません。秘密情報や他人の個人情報を渡す前に確認してください。</p><h2>削除と管理</h2><p>連携解除だけでGitHub上のファイルやGit履歴は消えません。外部AIへ渡した内容も相手側で管理してください。アプリ削除だけで外部フォルダやKeychainの情報がすべて消えるとは限りません。端末のクリップボードも必要に応じて消去してください。</p><h2>お問い合わせ</h2><p>公開する連絡方法を確認中です。この草稿をそのまま公開しません。</p><p><a href="privacy-en.html" lang="en">English</a></p>'''
page('memogyt/privacy.html','プライバシー',ja)
page('memogyt/privacy-en.html','Privacy','''<h1>Privacy policy</h1><p>Draft for the upcoming Mac/iPhone version and AI sharing. Effective date and contact method are pending.</p><h2>Local data</h2><p>No account is required for local editing. Notes, settings, backups and diagnostic logs are stored on your device. Note files are not encrypted by Memogyt. There is no proprietary advertising, analytics or automatic diagnostic-log upload.</p><h2>Optional GitHub integration</h2><p>Connection checks, downloads and requested sync operations communicate with GitHub. Typing does not send notes. Sync stores selected contents, filenames and change information in your repository. Public repositories expose that content publicly. PATs are stored in Keychain on Mac/iPhone and used for GitHub authentication. Memogyt does not send notes or credentials to a developer-operated server. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub's privacy statement</a>.</p><h2>Optional AI sharing and clipboard</h2><p>You review text before copying or choosing Send/Open. Copied text enters the system clipboard and may be retained or shared across devices according to OS settings. ChatGPT and Claude are opened without note text in the URL; you paste the text. Supported desktop Codex links may include the text in a launch URL, which may remain in OS or application records. On iPhone, Codex is opened without note text in the URL. Memogyt does not automatically submit messages or collect AI responses.</p><p>Shared content is handled under the destination service's terms, privacy policy and your account settings. Memogyt cannot control its retention, training use or deletion. Review confidential or personal information before sharing.</p><h2>Deletion and control</h2><p>Disconnecting does not delete GitHub files or history. Manage content shared with AI in the destination service. Uninstalling may leave external files and Keychain items. Clear the system clipboard when needed.</p><h2>Contact</h2><p>A public contact method is being selected. This unfinished draft will not be published.</p><p><a href="privacy.html" lang="ja">日本語</a></p>''',True)
page('memogyt/support.html','サポート','''<h1>使い方・サポート</h1><p class="lead">Memogytは無料のメモ帳です。個別の操作支援、回答期限、すべての不具合修正を保証していません。</p><h2>オフラインでも使えますか？</h2><p>メモの作成・編集は可能で、内容は端末に自動保存されます。GitHub同期や外部AIの利用には通信が必要です。</p><h2>AIへ本文が入りません</h2><p>共有 → AIで本文を確認し、「コピー」、続けて「送信／開く」を押してください。開いたアプリへ貼り付け、内容を確認して投稿します。送信先の仕様によって本文の直接受け渡しはできない場合があります。</p><h2>同期できません</h2><p>同期画面の詳細ログを確認し、通信状況、PATの期限・権限、リポジトリ設定を確認してください。ログや画面を公開する前に、PAT・メモ本文・個人情報を除いてください。</p><h2>お問い合わせ</h2><p>公開する連絡方法はレビュー後に決めます。現在この草稿から問い合わせを送ることはできません。</p><p><a href="support-en.html" lang="en">English</a></p>''')
page('memogyt/support-en.html','Support','''<h1>Help and support</h1><p>Memogyt is free. Individual assistance, response times and fixes for every issue are not guaranteed.</p><h2>Can I use it offline?</h2><p>Yes. Create and edit notes with automatic local saving. GitHub sync and external AI services require connectivity.</p><h2>Text did not appear in the AI app</h2><p>Choose Share → AI, review the text, press Copy, then Send/Open. Paste into the destination and review before posting. Direct handoff depends on the destination's capabilities.</p><h2>Sync failed</h2><p>Check the detailed sync log, connectivity, token expiry and permissions, and repository settings. Remove credentials, note contents and personal information before sharing logs or screenshots.</p><h2>Contact</h2><p>The public contact method will be selected after review. This draft cannot accept requests.</p><p><a href="support.html" lang="ja">日本語</a></p>''',True)
def language_links(body):
    body = re.sub(r' · <a href="(?:en|index|privacy-en|privacy|support-en|support)\.html" lang="(?:en|ja)">(?:English|日本語)</a>', '', body)
    body = re.sub(r'<p><a href="(?:privacy-en|privacy|support-en|support)\.html" lang="(?:en|ja)">(?:English|日本語)</a></p>', '', body)
    return body.replace('privacy-en.html', 'privacy.html').replace('support-en.html', 'support.html')

# Contact handling is separate from normal app use; the form remains unpublished.
pages['memogyt/privacy.html'] = pages['memogyt/privacy.html'].replace('<h2>お問い合わせ</h2>', '<h2>問い合わせ情報の取り扱い</h2><p>問い合わせ窓口にはGoogleフォームを使用する予定です。公開後に利用者が送信した問い合わせの種類・本文と、任意の利用環境・アプリのバージョン・返信先メールアドレスを、問い合わせ対応と製品改善のために取り扱います。入力内容はGoogleのサービスで処理・保存され、開発者が管理します。回答内容は一般公開しません。</p><p>通常のメモやPATを問い合わせ窓口へ自動送信することはありません。問い合わせにはパスワード・PAT・秘密のメモを入力しないでください。保管期間は公開前に確定します。<a href="https://policies.google.com/privacy">Googleのプライバシーポリシー</a>も確認してください。</p><h2>お問い合わせ</h2>')
pages['memogyt/privacy-en.html'] = pages['memogyt/privacy-en.html'].replace('<h2>Contact</h2>', '<h2>Inquiry information</h2><p>We plan to use Google Forms for support inquiries. After publication, the developer will handle the submitted inquiry type and message, along with any optional platform, app version and reply email, to respond to inquiries and improve the product. Google processes and stores this information as part of its services. Responses will not be publicly posted.</p><p>Memogyt does not automatically send notes or PATs to the contact form. Do not include passwords, tokens or private notes. The retention period will be finalized before publication. See <a href="https://policies.google.com/privacy">Google’s Privacy Policy</a>.</p><h2>Contact</h2>')

pages['memogyt/privacy.html'] = pages['memogyt/privacy.html'].replace('保管期間は公開前に確定します。', '問い合わせ情報は、対応・確認に必要な期間のみ保管し、不要になった時点で削除します。問い合わせ履歴の保存や復元は保証しません。')
pages['memogyt/privacy-en.html'] = pages['memogyt/privacy-en.html'].replace('The retention period will be finalized before publication.', 'Inquiry information is retained only as long as needed to handle and review the inquiry, and deleted when no longer needed. Preservation or recovery of inquiry history is not guaranteed.')

english_home = '''<section><p class="eyebrow">SMALL TOOLS, EVERYDAY IDEAS</p><h1>Grow your ideas with AI.</h1><p class="lead">Memogyt is a notebook for the AI era, with cloud sync through GitHub.<br>Capture ideas offline, connect with your favorite AI, and turn a conversation into your next step.</p></section><article class="card"><h2>Memogyt</h2><p>Write offline and share when you are ready. Supports text and Markdown.</p><a class="button" href="memogyt/index.html">Explore Memogyt</a></article>'''
english_intro = pages['memogyt/en.html'].replace('<h1>Capture ideas.<br>Keep them moving.</h1>', '<h1>Grow your ideas with AI.</h1>').replace('Memogyt saves notes on your device. Write offline, organize text and Markdown, and share an idea when you are ready.', 'Memogyt is a notebook for the AI era, with cloud sync through GitHub.<br>Capture ideas offline, connect with your favorite AI, and turn a conversation into your next step.')
for name in ('memogyt/privacy.html', 'memogyt/support.html'):
    pages[name] = pages[name].replace('公開する連絡方法を確認中です。この草稿をそのまま公開しません。', 'Googleフォームの問い合わせ窓口を準備しました。現在は未公開で、受付を開始していません。公開前の検証後、このページに問い合わせリンクを掲載します。').replace('公開する連絡方法はレビュー後に決めます。現在この草稿から問い合わせを送ることはできません。', 'Googleフォームの問い合わせ窓口を準備しました。現在は未公開で、受付を開始していません。公開前の検証後、このページに問い合わせリンクを掲載します。').replace('施行日と連絡先は未確定です。', '問い合わせフォームは作成済み・未公開です。施行日は公開前に確定します。')
for name in ('memogyt/privacy-en.html', 'memogyt/support-en.html'):
    pages[name] = pages[name].replace('A public contact method is being selected. This unfinished draft will not be published.', 'A Google Forms contact form has been prepared. It is unpublished and is not accepting inquiries. A contact link will be added here after pre-publication checks.').replace('The public contact method will be selected after review. This draft cannot accept requests.', 'A Google Forms contact form has been prepared. It is unpublished and is not accepting inquiries. A contact link will be added here after pre-publication checks.').replace('Effective date and contact method are pending.', 'The contact form has been created but remains unpublished. The effective date will be set before publication.')
for path, title, english in [
    ('index.html', 'Apps', english_home),
    ('memogyt/index.html', 'Memogyt', english_intro),
    ('memogyt/privacy.html', 'Privacy policy', pages['memogyt/privacy-en.html']),
    ('memogyt/support.html', 'Help and support', pages['memogyt/support-en.html']),
]:
    english = english.replace('to respond to inquiries and improve the product', 'to respond to and review inquiries')
    english = english.replace('the submitted inquiry type and message, along with any optional platform, app version and reply email', 'the submitted message, platform and app version, along with an optional reply email')
    pages[path] = pages[path].replace('問い合わせ対応と製品改善のため', '問い合わせの対応・確認のため')
    pages[path] = pages[path].replace('問い合わせの種類・本文と、任意の利用環境・アプリのバージョン・返信先メールアドレス', '問い合わせ本文・利用環境・アプリのバージョンと、任意の返信先メールアドレス')
    prefix = '../' * (len(Path(path).parts) - 1)
    nav = ''.join(f'<a href="{prefix}{target}">{label}</a>' for label, target in [('Apps','index.html'), ('Memogyt','memogyt/index.html'), ('Privacy','memogyt/privacy.html'), ('Support','memogyt/support.html')])
    japanese = language_links(pages[path]).replace('<h1>', '<h2>').replace('</h1>', '</h2>')
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | triplesky</title><link rel="stylesheet" href="{prefix}style.css"></head><body><header><a href="{prefix}index.html">triplesky / apps</a><nav aria-label="Main navigation">{nav}</nav></header><main><p class="notice">Unpublished preview. Contact details and effective date are pending.<br><span lang="ja">未公開のレビュー版です。連絡先・施行日は公開前に確定します。</span></p><nav aria-label="Page language"><a href="#english" lang="en">English</a><a href="#japanese" lang="ja">日本語 ↓</a></nav><section id="english" lang="en">{language_links(english)}</section><section id="japanese" lang="ja" aria-label="日本語"><hr><p class="eyebrow">日本語</p>{japanese}<p><a href="#english">English ↑</a></p></section></main><footer>triplesky · No advertising or analytics scripts on these pages.<br><span lang="ja">このページに広告・アクセス解析スクリプトはありません。</span><br><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a> — Hosting provider may process access information.<br><span lang="ja">公開時にはホスティング提供元がアクセス情報を取り扱います。</span></footer></body></html>'''
    out = root / path
    html = html.replace('Contact details and effective date are pending.', 'The contact form remains unpublished. Final checks and effective date are pending.').replace('連絡先・施行日は公開前に確定します。', '問い合わせフォームは未公開です。最終確認・施行日の確定を残しています。')
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(html, encoding='utf-8')
print(f'Created 4 bilingual pages: {root}')
